import{_ as d,C as s,o,c as e,j as i,E as l,a as n,a2 as r}from"./chunks/framework.C21TwvGF.js";const x=JSON.parse('{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (UX/UI)","link":"/mentor/10-sinf-uxui/"},"n":1,"bob":"I-bob · UX/UI dizaynning zamonaviy konsepsiyasi","lessons":[{"g":1,"title":"1-dars: UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi","lead":"UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi","link":"/mentor/10-sinf-uxui/hafta-01/dars-1","slide":"/slaydlar/10-sinf-uxui/hafta-01/dars-1.html","test":"/slaydlar/10-sinf-uxui/hafta-01/dars-1-test.html"},{"g":2,"title":"2-dars: Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD) tamoyillari va bosqichlari","lead":"Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD)","link":"/mentor/10-sinf-uxui/hafta-01/dars-2","slide":"/slaydlar/10-sinf-uxui/hafta-01/dars-2.html","test":"/slaydlar/10-sinf-uxui/hafta-01/dars-2-test.html"},{"g":3,"title":"3-dars: Interfeys dizaynida asosiy tamoyillar: Usability, Accessibility, Simplicity","lead":"Interfeys dizaynida asosiy tamoyillar: usability, accessibility, simplicity","link":"/mentor/10-sinf-uxui/hafta-01/dars-3","slide":"/slaydlar/10-sinf-uxui/hafta-01/dars-3.html","test":"/slaydlar/10-sinf-uxui/hafta-01/dars-3-test.html"}],"test":"/slaydlar/10-sinf-uxui/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-uxui/hafta-01/index.md","filePath":"mentor/10-sinf-uxui/hafta-01/index.md"}'),h={name:"mentor/10-sinf-uxui/hafta-01/index.md"},y={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function b(c,a,v,k,q,f){const t=s("Icon");return o(),e("div",null,[i("div",y,[i("h2",u,[l(t,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=r('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_1-dars-ux-dizaynning-strategik-roli-va-biznes-maqsadlari-bilan-uyg-unlashuvi" tabindex="-1">1-dars: UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi <a class="header-anchor" href="#_1-dars-ux-dizaynning-strategik-roli-va-biznes-maqsadlari-bilan-uyg-unlashuvi" aria-label="Permalink to &quot;1-dars: UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi&quot;">​</a></h2><ol><li>Mahalliy elektron do&#39;kon (yoki xizmat ko&#39;rsatish sayti) tanlang va uning bosh sahifasi hamda xarid jarayonini tahlil qiling.</li><li>Saytdagi 2 ta asosiy biznes maqsadi (masalan, konversiyani oshirish, savatni tark etishni kamaytirish)ni aniqlang.</li><li>Foydalanuvchilar xarid jarayonida duch kelishi mumkin bo&#39;lgan 2 ta og&#39;riqli nuqtani (pain point) yozing va ularga mos UX yechim taklif qiling.</li><li>Agar oyiga saytga 15 000 kishi tashrif buyursa va shulardan 450 nafari xarid qilsa, dastlabki konversiya foizini toping. Qulay UX evaziga xaridorlar 900 nafarga yetsa, konversiya necha foizga oshishini hisoblang.</li></ol><hr><h2 id="_2-dars-foydalanuvchiga-yo-naltirilgan-dizayn-user-centered-design-—-ucd-tamoyillari-va-bosqichlari" tabindex="-1">2-dars: Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD) tamoyillari va bosqichlari <a class="header-anchor" href="#_2-dars-foydalanuvchiga-yo-naltirilgan-dizayn-user-centered-design-—-ucd-tamoyillari-va-bosqichlari" aria-label="Permalink to &quot;2-dars: Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD) tamoyillari va bosqichlari&quot;">​</a></h2><ol><li>UCD ning 10 ta tamoyilidan kamida 3 tasini (masalan, Moslik, Qayta aloqa va Xatolarning oldini olish) o&#39;zingiz faol ishlatadigan mobil ilova (Telegram, Click, Uzum va h.k.) misolida tasvirlab bering.</li><li>Tizimdagi xatolik xabarlarini tahlil qiling: nima uchun &quot;Error 404&quot; yoki texnik kodlar o&#39;rniga samimiy va yechim ko&#39;rsatuvchi matn yozish zarurligini tushuntiring.</li><li>4 bosqichli UCD sikli (Kontekst -&gt; Talablar -&gt; Yechim -&gt; Baholash) bo&#39;yicha kichik xizmat (masalan, maktab oshxonasiga navbatsiz tushlik buyurtma qilish ilovasi) uchun har bir bosqichda nima ish qilinishini 1-2 jumlada bayon qiling.</li></ol><hr><h2 id="_3-dars-interfeys-dizaynida-asosiy-tamoyillar-usability-accessibility-simplicity" tabindex="-1">3-dars: Interfeys dizaynida asosiy tamoyillar: Usability, Accessibility, Simplicity <a class="header-anchor" href="#_3-dars-interfeys-dizaynida-asosiy-tamoyillar-usability-accessibility-simplicity" aria-label="Permalink to &quot;3-dars: Interfeys dizaynida asosiy tamoyillar: Usability, Accessibility, Simplicity&quot;">​</a></h2><ol><li>Usability, Accessibility va Simplicity tamoyillarining o&#39;zaro farqini va bir-birini qanday to&#39;ldirishini yozing.</li><li>WCAG rang kontrasti talabiga ko&#39;ra nega matn va fon kontrasti kamida 4.5:1 bo&#39;lishi kerakligini hayotiy misol bilan tushuntiring.</li><li>Hick qonuniga binoan ekrandagi tanlovlar soni ko&#39;payganda foydalanuvchida qanday muammo yuzaga kelishini ko&#39;rsating va uni soddalashtirish uchun 1 ta amaliy yechim bering.</li><li>Amazon&#39;ning &quot;1-Click&quot; yoki Airbnb&#39;ning inkluzivlik filtrlaridan birini tanlab, ushbu yechim qaysi tamoyilga mos kelishini tahlil qiling.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>1-dars vazifasi (30 ball):</strong> Biznes maqsadlari va foydalanuvchi og&#39;riqlarining to&#39;g&#39;ri bog&#39;langani, konversiya hisob-kitoblarining to&#39;g&#39;riligi.</li><li><strong>2-dars vazifasi (35 ball):</strong> UCD tamoyillari hayotiy ilovalarda to&#39;g&#39;ri aniqlangani, insoniy xatolik matnlari va 4 bosqichli sikl to&#39;g&#39;ri tushunilgani.</li><li><strong>3-dars vazifasi (35 ball):</strong> Usability vs Accessibility farqi, Hick va Miller qonunlarining to&#39;g&#39;ri talqin qilinishi hamda WCAG standartlarining anglangani.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar javoblarida nazariy qoidalarni yodlab aytish emas, real ilovalar va hayotiy vaziyatlar bilan bog&#39;lay olish qobiliyatiga asosiy e&#39;tiborni qarating.</li></ul>',16))]),i("div",m,[i("h2",g,[l(t,{name:"list-checks"}),a[3]||(a[3]=n(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=r('<p><strong>Mavzular:</strong></p><ol><li>UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi: ROI, Conversion Rate, Cart Abandonment Rate, 4 bosqichli model</li><li>Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD): Donald Norman (1993), UCD 10 ta tamoyili, ISO 9241-210 iterativ sikli</li><li>Interfeys dizaynida asosiy tamoyillar: Usability, Accessibility, Simplicity: Netflix, Google, Airbnb, Apple, Slack, Microsoft, Amazon keyslari, Hick va Miller qonunlari, WCAG kontrasti</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>UX Strategiyasi va Biznes Metrikalari</strong></td><td>UX va UI farqi, biznes maqsadlarini aniqlash, Conversion Rate va savatni tark etish formulasi, 4 bosqichli model amaliyoti</td><td>30 ball</td></tr><tr><td><strong>UCD Falsafasi va 10 ta Tamoyili</strong></td><td>Donald Norman merosi, UCD 10 ta tamoyilining amaliy ifodasi, tizim xatolik matnlarini insoniylashtirish, ISO 4 bosqichli iterativ sikli</td><td>35 ball</td></tr><tr><td><strong>Usability, Accessibility, Simplicity</strong></td><td>7 global tamoyil va yetakchi brendlar tahlili, Hick va Miller qonunlari asosida menyu soddalashtirish, WCAG rang kontrasti me&#39;yorlari</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>UX &amp; Biznes (30)</th><th>UCD Tamoyillari (35)</th><th>Usability &amp; WCAG (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar UX dizaynni ko&#39;pincha &quot;chiroyli rasm chizish&quot; (UI) deb yanglish tushunadilar. Ularga UX bu arxitektura, biznes daromadi (ROI, konversiya) va inson psixologiyasi ekanini doimiy ravishda eslatib turish muhim. Shuningdek, dizayner o&#39;z didiga emas, balki real foydalanuvchilar ehtiyojiga suyanishi kerakligi (False-Consensus Effect) qayta-qayta uqtirilishi lozim.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> Real elektron tijorat saytida (masalan, mahalliy onlayn do&#39;konda) savatdan to&#39;lovgacha bo&#39;lgan yo&#39;lni audit qilib, Hick qonuni va WCAG kontrast me&#39;zonlari bo&#39;yicha to&#39;liq taqdimot tayyorlash topshirig&#39;i tavsiya etiladi.</li></ul>',11))])])}const U=d(h,[["render",b]]);export{x as __pageData,U as default};
